@MainActor func transient_SymbolPin_issues (
       _ self_xPin : CanariLength,          
       _ self_yPin : CanariLength,          
       _ self_xName : CanariLength,         
       _ self_yName : CanariLength,         
       _ self_xNumber : CanariLength,       
       _ self_yNumber : CanariLength,       
       _ self_name : String
) -> CanariIssueArray {
//--- START OF USER ZONE 2
  var issues = [CanariIssue] ()
  if self_name.isEmpty {
    issues.appendSymbolEmptyPinNameIssueAt (x: self_xName, y: self_yName)
  }
  if (self_xPin.cuValue % (SYMBOL_GRID_LENGTH.cuValue * 4)) != 0 {
    issues.appendSymbolPinHorizontalIssueAt (x: self_xPin, y: self_yPin)
  }
  if (self_yPin.cuValue % (SYMBOL_GRID_LENGTH.cuValue * 4)) != 0 {
    issues.appendSymbolPinVerticalIssueAt (x: self_xPin, y: self_yPin)
  }
  if (self_xName.cuValue % SYMBOL_GRID_LENGTH.cuValue) != 0 {
    issues.appendSymbolHorizontalIssueAt (x: self_xName, y: self_yName)
  }
  if (self_yName.cuValue % SYMBOL_GRID_LENGTH.cuValue) != 0 {
    issues.appendSymbolVerticalIssueAt (x: self_xName, y: self_yName)
  }
  if (self_xNumber.cuValue % SYMBOL_GRID_LENGTH.cuValue) != 0 {
    issues.appendSymbolHorizontalIssueAt (x: self_xNumber, y: self_yNumber)
  }
  if (self_yNumber.cuValue % SYMBOL_GRID_LENGTH.cuValue) != 0 {
    issues.appendSymbolVerticalIssueAt (x: self_xNumber, y: self_yNumber)
  }
  return issues
//--- END OF USER ZONE 2
}

